func jsonStr(s string) string {
	b := []byte{'"'}
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b = append(b, '\\', byte(r))
		case r < 32:
			b = append(b, []byte(fmt.Sprintf("\\u%04x", r))...)
		default:
			b = append(b, []byte(string(r))...)
		}
	}
	return string(append(b, '"'))
}

func joinComma(xs []string) string {
	s := ""
	for i, x := range xs {
		if i > 0 {
			s += ","
		}
		s += x
	}
	return s
}

func civil(days int64) string {
	z := days + 719468
	era := z
	if z < 0 {
		era = z - 146096
	}
	era /= 146097
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	d := doy - (153*mp+2)/5 + 1
	m := mp - 9
	if mp < 10 {
		m = mp + 3
	}
	y := yoe + era*400
	if m <= 2 {
		y++
	}
	return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
}

// PurchaseRouteRecord One call as a record in the fixtures format (docs/formats.md): the inputs, what came out, and the rows that matched, as one JSON line. An empty tag is left out.
func PurchaseRouteRecord(in Input, out Output, trace []Fired, tag string) string {
	ins := []string{}
	ins = append(ins, fmt.Sprintf("\"reviewer_given\":%s", fmt.Sprint(in.ReviewerGiven)))
	ins = append(ins, fmt.Sprintf("\"kind\":%s", jsonStr(in.Kind.String())))
	ins = append(ins, fmt.Sprintf("\"amount\":%s", fmt.Sprint(int64(in.Amount))))
	ins = append(ins, fmt.Sprintf("\"advance\":%s", fmt.Sprint(int64(in.Advance))))
	obs := []string{}
	obs = append(obs, fmt.Sprintf("\"first\":%s", jsonStr(out.First.String())))
	if out.Technical == nil {
		obs = append(obs, "\"technical\":null")
	} else {
		obs = append(obs, fmt.Sprintf("\"technical\":%s", jsonStr((*out.Technical).String())))
	}
	if out.Finance == nil {
		obs = append(obs, "\"finance\":null")
	} else {
		obs = append(obs, fmt.Sprintf("\"finance\":%s", jsonStr((*out.Finance).String())))
	}
	if out.Board == nil {
		obs = append(obs, "\"board\":null")
	} else {
		obs = append(obs, fmt.Sprintf("\"board\":%s", jsonStr((*out.Board).String())))
	}
	obs = append(obs, fmt.Sprintf("\"decide\":%s", jsonStr(out.Decide.String())))
	obs = append(obs, fmt.Sprintf("\"inform\":%s", jsonStr(out.Inform.String())))
	rows := []string{}
	for _, f := range trace {
		lbl := ""
		if f.Label != "" {
			lbl = fmt.Sprintf(",\"label\":%s", jsonStr(f.Label))
		}
		rows = append(rows, fmt.Sprintf("{\"table\":%s,\"row\":%d%s}", jsonStr(f.Table), f.Row, lbl))
	}
	head := "{"
	if tag != "" {
		head = fmt.Sprintf("{\"tag\":%s,", jsonStr(tag))
	}
	return fmt.Sprintf("%s\"in\":{%s},\"observed\":{%s},\"trace\":[%s]}", head, joinComma(ins), joinComma(obs), joinComma(rows))
}
